/**
  * @brief  Read button with software debouncing
  * @retval true if button pressed, false otherwise
  */
static bool Button_ReadDebounced(void)
{
    GPIO_PinState reading = HAL_GPIO_ReadPin(BUTTON_GPIO_PORT, BUTTON_PIN);

    /* Check if reading changed */
    if (reading != last_button_state)
    {
        last_debounce_time = HAL_GetTick();
    }

    /* Check if debounce time has passed */
    if ((HAL_GetTick() - last_debounce_time) > DEBOUNCE_DELAY_MS)
    {
        /* Check if state changed */
        if (reading != button_state)
        {
            button_state = reading;

            /* Return true on button press (HIGH to LOW with pull-up) */
            if (button_state == GPIO_PIN_RESET)
            {
                last_button_state = reading;
                return true;
            }
        }
    }

    last_button_state = reading;
    return false;
}

